INSERT INTO `everlake_forge_stage` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(86746, 0, 0, 0, 0, 0, 0, 0, 0, 'Thank you. While the Legashi are numerous, any one slain is a furbolg life saved.$B$BIf you are able, there is much more to be done in our struggle against the satyr. You would prove yourself an ally to the other furbolg of Ursolan as well.', 0),
(86752, 0, 0, 0, 0, 0, 0, 0, 0, 'Hail, $C. Until our chieftain returns, I serve as leader of the Blackmaw furbolg. I have heard of the help you\'ve given our tribe, and I am grateful.$B$BNo doubt Ekkal has told you of the great threat the satyr pose to my people. If you will aid us in our plight, then I welcome you.', 0),
(86798, 0, 0, 0, 0, 0, 0, 0, 0, 'You bring news from the Blackmaw of Azshara? We had taken them for dead.', 0),
(86814, 0, 0, 0, 0, 0, 0, 0, 0, 'We have won a great victory today! Where once the Legashi were the terrors of Azshara, their leaders now lie slain at our feet! Only that loathsome fiend Varrox remains.', 0),
(88807, 0, 0, 0, 0, 0, 0, 0, 0, 'A commendable first step, $C. Now we strike the ruins proper.', 0),
(88809, 0, 0, 0, 0, 0, 0, 0, 0, 'Our work in Eldarath is far from over, but victory rarely comes in one fell swoop. We must keep up our efforts.', 0),
(91548, 0, 0, 0, 0, 0, 0, 0, 0, '<Zevrost takes the heart, eyes hungry>$B$BHa ha! Excellent work, $N! I will savor this power.', 0),
(91697, 0, 0, 0, 0, 0, 0, 0, 0, '<The elder sniffs you.>$B$BYou have to work on that smell. Too clean. Berries give you sweet scent.', 0),
(92008, 0, 0, 0, 0, 0, 0, 0, 0, 'Yes, of course I have Kaylaena\'s order. I was wondering when she would pick it up!$B$BEvery time she gets an order picked up, it\'s a new face I see running errands for her! What\'s she up to now anyway? Still trying to make the perfect trinket to fend off rogues in duels?', 0),
(92009, 0, 0, 0, 0, 0, 0, 0, 0, 'Hey, you made it back in one piece! I knew you could do it, and that crate looks no worse for the wear!$B$BLet me take care of those inverted mana cells, I know how much trouble they are to ship in a package. That... may have been why I was putting off this chore for so long.', 0),
(92015, 0, 0, 0, 0, 0, 0, 0, 0, 'Not the kind of skunk-works you were expecting, is it? The right person comes along for every job, even the ones that stink.$B$BNow that I can get to more of these tools, I\'ll put together a thing or two here that might help us both out.', 0),
(92064, 0, 0, 0, 0, 0, 0, 0, 0, 'Yikes! Enough! That\'s as close as I\'m willing to cut it.$B$BYou cut loose the pilot\'s survival kit that I couldn\'t reach!', 0),
(92102, 0, 0, 0, 0, 0, 0, 0, 0, 'This is where the world, as we knew it, ended. I\'m here to tell you how it happened.', 0),
(92111, 0, 0, 0, 0, 0, 0, 0, 0, 'Yes, I could tell a new face must be here. No fur nor fang, and a fresh smell to keep.$B$B<Osi sniffs you thoughtfully.>', 0),
(92328, 0, 0, 0, 0, 0, 0, 0, 0, 'Alright, that didn\'t go quite to plan. Thanks for giving it a crank, at least we know only a few parts are faulty and not the whole engine.$B$BThere\'s still plenty here that is working, though! I\'ve got an idea of how we might still make use of this stationary artillery.', 0),
(92329, 0, 0, 0, 0, 0, 0, 0, 0, 'Better off being the glaive thrower that takes the brunt of it than us. Well, judging by how angry you made it, Ghansurok didn\'t like that very much and will think twice about loitering around Hyjal now.$B$BThanks again for all your help, I learned so much! The next project will be more than that old war machine ever could\'ve been.', 0),
(92345, 0, 0, 0, 0, 0, 0, 0, 0, 'A tunnel beneath Nordrassil, you say? You certainly have my attention.', 0),
(92594, 0, 0, 0, 0, 0, 0, 0, 0, 'Thank you for handling that overgrowth. Judging by the hitchhikers your boots picked up, you crushed them well, too!', 0),
(92754, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, you came through for us. The Magram clan will never forget your contributions. When we come to rule over Desolace, you and your kind will be spared from our wrath.', 0),
(92872, 0, 0, 0, 0, 0, 0, 0, 0, 'The torches within this chamber burned more brightly when you cast that small satchel into the sea, and it\'s how we know you were true to the simple but important rites you were trusted to conduct.', 0),
(92959, 0, 0, 0, 0, 0, 0, 0, 0, 'I hope... that you saw something beautiful spring from this terrible violence.$B$BSoon I, too, will return to the earth... but new blossoms will carry forward a future... for the mountain.', 0),
(93016, 0, 0, 0, 0, 0, 0, 0, 0, 'I hope that explanation alleviated any concerns you might have had, $N. As you see, I was not acting out of any foul intent, and my failure to explain the situation thoroughly from the start was purely due to my enthusiasm of having a chance to see the crystals\' lights shine again.$B$BI am excited to visit the temple of Shen\'dralas again, though it may take some time before I muster the courage to speak with the Shen\'dralar there.$B$BYou, on the other hand...', 0),
(93066, 0, 0, 0, 0, 0, 0, 0, 0, 'I am sorry you have come all this way, outsider, but you are not needed at the Magram front. Already you have distracted me long enough to delay our work.$B$BReturn to Orgrul and tell him--$B$BOn second thought, I do have something for a disposable soldier such as yourself. This will be quick, for better or worse.', 0),
(93072, 0, 0, 0, 0, 0, 0, 0, 0, 'My scouts have already reported your success. Now perhaps we can continue our training in peace. The Gelkis need to learn that this place, and the Desolace, belong to centaur born of Magram blood.$B$BIf you see any stragglers, cut off their heads too. They should be afraid to ever step hoof outside of their little hovel.$B$BThat will belong to us too, someday soon.', 0),
(93125, 0, 0, 0, 0, 0, 0, 0, 0, 'Rokren, yes! We spoke briefly as he passed by. I am grateful that he is alive and well.$B$BBetween the other Gelkis you rescued and Rokren, I am feeling a renewed sense of hope and courage. Our clan\'s true numbers are higher than we thought, and so many \"outcasts\" here were Gelkis lured out and held against their will.$B$BThere is a chance the Gelkis will survive this, $N.', 0),
(93362, 0, 0, 0, 0, 0, 0, 0, 0, 'Eventually, I think the gardens will bloom beautifully again. Those flowers you culled today will give themselves back to the soil. It may take some time, perhaps a few generations, but someday it will be restored.$B$BYou have done a very kind deed, $N. You have my personal gratitude.', 0),
(93404, 0, 0, 0, 0, 0, 0, 0, 0, '<The flames that previously burned away at the treant\'s ghostly form have faded. Still, his gaze is hollow. It takes several moments of inaction before he regards your presence.>$B$BMy torment has ended. Peace approaches me.$B$BNo time for farewells. No time to wait for those that have forgotten me.$B$BTraveler, I have one final thing to say. One last hope for your quest.', 0),
(93422, 0, 0, 0, 0, 0, 0, 0, 0, '$N, this would have been most damaging to our efforts to rally against the Wild King if it had been delivered! We will take what little we can glean from this message and inform our druids. Thank you.', 0),
(93551, 0, 0, 0, 0, 0, 0, 0, 0, 'This is where the world, as we knew it, ended. I\'m here to tell you how it happened.', 0),
(93584, 0, 0, 0, 0, 0, 0, 0, 0, 'What a mess. Druids having to fight other druids... I never thought it would come to this.$B$BHopefully we can get this all sorted out soon.', 0),
(93594, 0, 0, 0, 0, 0, 0, 0, 0, 'It is too late. For these gardens.$B$BI am the last of my generation of caretakers. Without the gift, more cannot take my place.$B$BThe weeds have overtaken the land. The flowers are restless. The trees wither.$B$B<Woodwyrd slowly turns toward the towering ancient illuminating the sky with its endless fire.>', 0),
(93601, 0, 0, 0, 0, 0, 0, 0, 0, 'Big Undead want necklace? Well, Big Undead can\'t have!$B$BThornweavers need necklace. Land is deader than dead. Thorns no sprout without necklace! Centaur tread where thorns no sprout. See problem, or Big Undead blind?$B$B<Kog\'thug pauses his condescending ramble and snorts thoughtfully.>$B$BKog\'thug have idea. Want trade?', 0),
(93604, 0, 0, 0, 0, 0, 0, 0, 0, '<The quilboar\'s expression lit up immediately upon catching sight of the blood-filled vials. The intensity of his emotions was so great that it displaced the helmet resting haphazardly over his brow.>$B$BBlood of Agamaggan! You got it!$B$B...Kog\'thug expected you to die. Did not expect return. Big $R put Kog\'thug in complicated situation.$B$B<Kog\'thug hesitated before speaking again.>', 0),
(93606, 0, 0, 0, 0, 0, 0, 0, 0, 'I see. Kog\'thug never say sorry face-to-face. Always sending someone to speak for him. Are these flowers from him? Or did Kog\'thug send you to fetch these too?$B$B<Quolga listens to your overly truthful explanation of the situation. The thornweaver is extremely unamused by the facts and heaves out a sigh.>$B$BStupid boar.$B$BThis trinket ran out of power weeks ago and no longer serves us any purpose. $B$BIt\'s yours now. Leave the blood. Keep the flowers.$B$BGo away.', 0),
(93826, 0, 0, 0, 0, 0, 0, 0, 0, 'The forest sleeps now.', 0),
(93833, 0, 0, 0, 0, 0, 0, 0, 0, 'Fine plumage on these, and you didn\'t mangle their bodies, either. You show sincerity, young one.', 0),
(94220, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, you are delivering my dagger? Hah, I suppose my threat rang quite hollow then, hm?$B$BI must stay on high alert given my duties here, and especially with oth-- ahem, the foul Syndicate roaming about elsewhere here.$B$BWould you be so kind as to part with the blade, now? I must get back to my task.', 0),
(94224, 0, 0, 0, 0, 0, 0, 0, 0, 'Whoa. You came well prepared! Hope that mace is for me, unless you plan to do ALL of the fighting.', 0),
(94225, 0, 0, 0, 0, 0, 0, 0, 0, 'These are the leggings I ordered, huh? \"Three to five business days,\" they said. More like three to five business MONTHS!$B$BI submitted this when I was working for the Venture Co out there, and let me just say, that partnership is well over with, so we can consider this order expired.$B$BWhy aren\'t you leaving yet? Ugh, fine! Here\'s your payment.', 0),
(94226, 0, 0, 0, 0, 0, 0, 0, 0, 'Mmph. Seems to have been a severe mistranslation. I did not ask for green iron gauntlets--I specifically requested green iron knuckles.$B$B<MacKinley fakes an uppercut in your direction, stopping himself a small but calculated distance from cracking your jaw.>$B$BThese\'ll knock someone out cold anyway. I suppose I can use these while I wait for a replacement.$B$BHere\'s your payment. Oh, you expected more? Well, so did I.', 0),
(94228, 0, 0, 0, 0, 0, 0, 0, 0, 'At last! I\'ve been stomping around the wetlands with soggy feet for days!$B$BHopefully these aren\'t prone to rusting either. I trust you know what you\'re doing.', 0),
(94232, 0, 0, 0, 0, 0, 0, 0, 0, 'I don\'t know what I expected when I sent out an order for a curse dispelling device, but this Minor Recon--Racom--ugh, Minor Whatchamacallit sure ain\'t it!$B$BLook, I know how complicated the refund process is and I do NOT have time for that. It\'s way easier for us both if I just take this off your hands, and I\'ll be more specific with my next order.$B$BFor both of our sakes, let\'s hope you don\'t screw that one up too!', 0),
(94234, 0, 0, 0, 0, 0, 0, 0, 0, 'My new shadow goggles!$B$B<Without another word, the goblin tossed a handful of coins your way with one hand while the other swiped the item out of your grasp. The transaction was completed and his attention lost before you had a moment to process what happened.>', 0),
(94236, 0, 0, 0, 0, 0, 0, 0, 0, 'Hey, there\'s the bomb I ordered!$B$BWell, one of them anyway. I needed a variety pack! You know, enough so I can test each one for effectiveness AND have a few leftover for my own needs!$B$BWell, whatever. Here\'s a cut of your cut--I\'ll give you the rest when you bring ME my full order!', 0),
(94237, 0, 0, 0, 0, 0, 0, 0, 0, 'I am glad you arrived when you did. A few Dragonmaw orcs stormed by the other day and gave me the stink eye.$B$BI ran out of ammunition on my way here. It\'s half the reason I haven\'t left this wretched place yet!$B$BThe other half being that I still have profits to make.$B$B<Kixxle greedily rubs his hands.>', 0),
(94238, 0, 0, 0, 0, 0, 0, 0, 0, 'Wut dis? Dis the ball me was dreaming of?$B$BYou, $R, give ball to me?$B$B<Sos\'mol pauses, tears well in his eyes.>$B$BDis is happiest day of ogre life... Dis so much more important than... uhh... what was da other thing me wanted?$B$BNo remember. Ball most important now.$B$BT\'anks!!', 0),
(94239, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh! The pants? Ah, I realized shortly after writing this that I needed a full set of clothes - new overalls included.$B$BIf it will get you out of my hair, I suppose I should honor the request. After all, you did make an arduous journey to find me.$B$BTake this, now please...$B$B<She gestured in a polite but firm shooing motion.>', 0),
(94240, 0, 0, 0, 0, 0, 0, 0, 0, '<Murache gestures down the hillside toward the lake sprawling with monstrous vegetative creatures.>$B$BThese beasts are fascinating. I have been observing them for a few days now. I believe they have much to teach us in regards to herbalism and farming techniques. The gloves you brought seem perfect for the task; I tried handling them barehanded once and had to pull thorns out of my fingers for hours.$B$BIf I discover anything interesting, you will be the first to know, friend.', 0),
(94242, 0, 0, 0, 0, 0, 0, 0, 0, 'Yes, good. I appreciate the craftsmanship and the expedience. I will put in a good word to my superiors about you.$B$BHow does \"$N of the Syndicate\" sound? Keep up the good work and that title might be yours one day!', 0),
(94244, 0, 0, 0, 0, 0, 0, 0, 0, 'Thar be me shoulderpads, at last!$B$BEver had one of these squakers perch on your shoulder? Bet ye\' haven\'t! Their claws, they hurt!$B$BNow they got a place to rest all day, and you have a heavier coinpurse!$B$B<Narkk eyes said coinpurse.>$B$BFor now!', 0),
(94245, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, thank gold my new gloves FINALLY arrived.$B$BYou have no idea how long I have been waiting for these. All these other gobs insist on working barehanded, but that\'s how you lose a fingernail. Or a finger!$B$B<The pit boss swiftly removes his old grimy gloves and swipes his new pair right out of your hands.>', 0),
(94246, 0, 0, 0, 0, 0, 0, 0, 0, 'Are these Red Whelp Gloves? I have heard they are very expensive to craft, but worth every copper. I was thinking about gearing up to knock a few of those lil\' dragons down up to the northeast, but I\'ve heard they can breathe fire.$B$BAnyway, I will take those off your hands and slide them right onto mine! Thanks, pal!', 0),
(94250, 0, 0, 0, 0, 0, 0, 0, 0, 'Ha ha! Thanks, pal. I owe you.$B$B<Kzixx reaches into a Small Silk Pack already in his possession, filled to the brim with coin, and pulls out a fist full. He counts out a tiny fraction of his total wealth, and hands it to you.>$B$BThis should cover it. No take-backs!', 0),
(94251, 0, 0, 0, 0, 0, 0, 0, 0, 'Hmm.$B$BI think you be a lil\' lost if you think these gaudy pants were somethin\' I be after.$B$BI\'ll take \'dem off your hands anyway. You never know when another adventurer be needin\' a new pair!', 0),
(94252, 0, 0, 0, 0, 0, 0, 0, 0, 'When I worked for the Venture Co, I had to wear these boots all day, every day. I thought I would be able to take these off and get comfortable in my own hut, but I didn\'t think of it until after I tracked mud everywhere.$B$BThese boots? They look way more comfortable. Second best thing to running around barefoot!', 0),
(94253, 0, 0, 0, 0, 0, 0, 0, 0, 'I plan to be sneakin\' into the gates of Zul\'Gurub soon, but I need the gear to blend in. Thinkin\' I gear up like one of their ritualists.$B$BThis colorful kilt is exactly what I be needin\'.', 0),
(94257, 0, 0, 0, 0, 0, 0, 0, 0, 'You are not the first outsider to have assisted me, $N. By now I have come to learn that it is a fault of mine to assume the worst of any that approach me. Never would I have imagined that it would be centaur who I view with such animosity, while others from far beyond the desert would be the ones with whom I ally.$B$BDo not mistake this transaction as the beginnings of a friendship, but know that this deed will be remembered.', 0),
(94258, 0, 0, 0, 0, 0, 0, 0, 0, 'Puny $C bring Mudcrush tasty drink!$B$B<Durtfeet swipes the potion from your hand, nearly taking your hand with it. He gulps it down without a second thought.>$B$BDrink tasty, AND Mudcrush feel tough as rocks now!', 0),
(94259, 0, 0, 0, 0, 0, 0, 0, 0, 'We are in dire need of more of these potions here in Felwood. Though there are many corruptive forces at play here, nature itself is known to lash out violently when provoked.$B$BI suspect this will not be the last time you replenish our supply, $N. Thank you kindly for your assistance.', 0),
(94260, 0, 0, 0, 0, 0, 0, 0, 0, 'Particularly at night, it is a challenge to see even the local wildlife that makes no attempt to conceal itself.$B$BConsider then how difficult it might be to spot an assailant intentionally staying hidden.$B$BThis draught will help keep my senses sharp.', 0),
(94261, 0, 0, 0, 0, 0, 0, 0, 0, 'Balance must be maintained in this grove, but despite our wishes, that includes countering constant peace with the chaos of rage.$B$BAt times, a few among the experienced druids partake in violent rituals secluded away from the rest of us here in Nighthaven.$B$BA great rage potion, such as this, is a necessary part of that to overcome their natural inclination to embrace their inner tranquility they have worked so hard to master.', 0),
(94262, 0, 0, 0, 0, 0, 0, 0, 0, 'I take it back! Mana potions aren\'t the most exciting delivery to receive, but I work with whatever I can take.$B$BHere\'s your cut. Now, like I said before, move along.', 0),
(94264, 0, 0, 0, 0, 0, 0, 0, 0, '\'Dis be only one of \'da many reagents I be needin\' for my ritual.$B$BNever \'da less, it be one less I now need to be collectin\'.$B$BIf ya\' find anythin\' else curious, bring it to me first.', 0),
(94265, 0, 0, 0, 0, 0, 0, 0, 0, 'Is this... Goblin Rocket Fuel!?$B$B<Pestlezugg brings the container lightly near his nose and enjoys a whiff.>$B$BI love the smell of explosives in the morning...$B$BNixx across town refuses to give me his recipe for fuel, preferring to import it from a supplier who-knows-where. What a stupid goblin! He has an eager alchemist RIGHT HERE who would love the business!$B$BAnyway I figured I\'d follow him around and order from his source and see if I can figure it out myself.$B$BDon\'t tell him!', 0),
(94266, 0, 0, 0, 0, 0, 0, 0, 0, 'I learned quick upon my exile that my old age has already caught up to me. Even the life-or-death task of venturing away from my homeland proved challenging.$B$BAs I continue to learn how to truly fend for myself in all regards, I send help to others in the meantime. Your delivery of this elixir is one of many similar thus far. I appreciate your willingness to assist someone who, mere months ago, might have branded you instantly as a threat to eliminate.$B$BPlease take this coin as my thanks.', 0),
(94267, 0, 0, 0, 0, 0, 0, 0, 0, 'Wait, you brought me a drink--?$B$BAh. Non-alcoholic I see. I\'m not sure how things got messed up in translation, but I am definitely not on the lookout for a \"Wildvine Potion.\" A Wildvine Noir maybe...$B$BBut I bet even this tastes better than the sludge they expect me to drink around here. Just pass it here.', 0),
(94268, 0, 0, 0, 0, 0, 0, 0, 0, 'Wait, wait, wait! Is that a Steel Plate Helm I see?$B$BEither this is a wild coincidence or you\'re the guy who found my note! Whew, I was worried for a little bit, thought one of the foremen was going to stumble upon it first. No chance I would have been paid.$B$BSo, uh, you willing to part with that?', 0),
(94269, 0, 0, 0, 0, 0, 0, 0, 0, 'My part finally arrived! The profits are only going to skyrocket from here.$B$BHere\'s your cut.', 0),
(94270, 0, 0, 0, 0, 0, 0, 0, 0, 'This weapon chain? This keep club in hand?$B$BUgbert thank you. Ugbert strongest ogre in all of Dustwallow!', 0),
(94271, 0, 0, 0, 0, 0, 0, 0, 0, 'It would seem you are the one to help me instead.$B$BHere is your payment.', 0),
(94272, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, a replacement weapon. Well timed, as my last was stolen by a gnoll!', 0),
(94273, 0, 0, 0, 0, 0, 0, 0, 0, 'What a magnificent blade! I have been seeking a new weapon for my own use for quite some time, and I think you have brought it right to me.$B$BThank you, $C. Your kindness will be remembered.', 0),
(94274, 0, 0, 0, 0, 0, 0, 0, 0, 'Ooh.$B$B<Without another word, Spek swipes the coif away from your hand and jingles a few coins before tossing them haphazardly in your direction.>$B$BNext!', 0),
(94275, 0, 0, 0, 0, 0, 0, 0, 0, 'My sharpening stones, eh? These don\'t look very sharp to me!$B$B<Burninate struggles to suppress a smirk as he waits for you to laugh at his lame joke.>$B$BBah! Just hand them over! Maybe you\'ll be able to afford yourself a sense of humor with these coins.', 0),
(94276, 0, 0, 0, 0, 0, 0, 0, 0, '\'Da most important part of any good ritual... a wicked blade with which to draw blood!$B$BBlood will be spilled, indeed.', 0),
(94277, 0, 0, 0, 0, 0, 0, 0, 0, 'So there I was, messin\' with the controls like I usually do. Pull a lever here, push a button there, y\'know, the usual stuff.$B$BThen, when I wasn\'t looking, one of the levers popped right off! I thought I\'d be able to jam it back in but that just caused more damage.$B$BSo I put in a request for a new, durable part--a truesilver rod--that you are delivering right now!$B$BOnce again, Spigot Operator Luglunket took matters into his own hands and came out on top. I will be taking this from you, now.', 0),
(94279, 0, 0, 0, 0, 0, 0, 0, 0, 'This delivery of yours surprises me. I requested a simple replacement weapon from a blacksmith that often visits Marshal\'s Refuge, one that I anticipated claiming during my next visit to camp.$B$BI feel much safer venturing through the crater with a backup weapon. It looks sharp enough to take anything down except for the largest devilsaurs.$B$BThank you, shaman.', 0),
(94280, 0, 0, 0, 0, 0, 0, 0, 0, 'What is that in your hand? Oh, is that the Mechanical Dragonling I ordered?$B$BNo way, you are a lifesaver, $N! I was just making the final calculations here before hoofing it all the way back to Gadgetzan, just so I could get some proper surveying equipment and then lug myself all the way back. Would NOT have been a fun time.$B$BNow I can use this to scout up the mountains and have some real data to bring back with me!$B$B...This little guy DOES have a camera or something, right?', 0),
(94281, 0, 0, 0, 0, 0, 0, 0, 0, 'An advanced target dummy? Well, I was hoping for a gun really, but maybe this will be enough of a distraction to slip away if they ever get a wild idea to start chasing me around.$B$BDoes it flail around? I hope it flails around.', 0),
(94282, 0, 0, 0, 0, 0, 0, 0, 0, '<Rather than question the current predicament, you carefully reach forward with the Craftsman\'s Monocle in hand and place it vaguely where a monocle might be on an ordinary person.$B$BThe slime responds in kind, expelling out a handful of coins from elsewhere on its body. How disgusting.>', 0),
(94283, 0, 0, 0, 0, 0, 0, 0, 0, 'You may think it curious that an elven huntress has a need for shoddy goblin explosives.$B$BThough I trust my bow and the ferocity of Della, I am looking to expand my arsenal before venturing to Jaedenar. I do not know all of the tricks that the satyr and their allies possess, but I will be prepared.', 0),
(94284, 0, 0, 0, 0, 0, 0, 0, 0, 'A long-awaited delivery is an even better surprise.$B$BI find it challenging to keep my eyes sharp with so many predators skulking about these woods. These goggles ought to help with that.', 0),
(94285, 0, 0, 0, 0, 0, 0, 0, 0, '<Narianna inspects the unstable trigger by curiously examining it from multiple perspectives.>$B$BTruth be told, $N, I was hoping for a device that was a little... simpler to understand. I am not an engineer myself, but had the hope that I could do a little tinkering with one of my bows. I can now confidently say that this is not a path for me to follow.$B$BYou will not leave empty handed, however. Please take this for your trouble.', 0),
(94286, 0, 0, 0, 0, 0, 0, 0, 0, 'Whoa, whoa! Don\'t be waving one of those out in the open like that! Bruisers patrol this road too, pal, and I can\'t have them asking questions.$B$BHand it over before you make me look suspicious.', 0),
(94288, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, you\'re just the delivery boy, never mind on that offer. I doubt you\'d survive.$B$BThese bombs though? Exactly what Bigblast ordered. I\'m out here planning a possible new Steamwheedle-- actually, y\'know what, I bet you aren\'t interested, so I will keep my trap shut.', 0),
(94289, 0, 0, 0, 0, 0, 0, 0, 0, 'You aren\'t going to believe this, $R, but I made a very careless mistake!$B$BI was lugging my big toolbox over here to make some very calculated adjustments when I tripped! Fortunately nothing was damaged, but my gyromatic micro-adjuster landed on the teleport pad and... well, it\'s gone!$B$BWait, are you the one to deliver my replacement micro-adjuster? If you are, hand it over, quick, quick!!', 0),
(94290, 0, 0, 0, 0, 0, 0, 0, 0, 'Wha--what ish thish...? Hiccup!$B$BI don\' remember orderin\' any--hiccup!--whatchama-repair-kits.$B$BUrgh, alright stop yapping, I\'ll pay whatever it is! Hiccup!', 0),
(94292, 0, 0, 0, 0, 0, 0, 0, 0, 'Is that hat for me? If it is not, I nonetheless hope you are willing to part with it.$B$BHere is what I have to trade. I wish I could offer greater compensation, but as much as I wish for a comfortable hat, I also wish for my pockets to not be empty should the need arise for more goods or services.', 0),
(94293, 0, 0, 0, 0, 0, 0, 0, 0, 'While I am glad to have this cloak in my possession, I will confess I was hoping for some assistance as well.$B$BI intend to use this to wrap any artifacts we may extract from the area for their own safekeeping, and to hide them away from the greedy eyes of the naga and centaur here.$B$BThank you, $N.', 0),
(94294, 0, 0, 0, 0, 0, 0, 0, 0, '<You aren\'t quite sure where to put the bracers, so you begin to place them nearby on a pile of debris.$B$BThe slime leers forward, silently threatening to make you its next meal.$B$BInstead, you quickly toss the bracers haphazardly toward the creature. It devours its leathery meal, and spits out a few coins as payment. It no longer seems to have a hungering demeanor toward you, for now.>', 0),
(94295, 0, 0, 0, 0, 0, 0, 0, 0, 'My mistake, I had forgotten about this request some time ago.$B$BI needed a proper helmet when walking around Felwood during rainy nights. Perhaps I have become overly cautious, but I do not even trust the raindrops in this wood anymore.$B$BThank you.', 0),
(94296, 0, 0, 0, 0, 0, 0, 0, 0, 'Sure enough, I was right.$B$BThank you, $C. I am still recuperating my losses after being ambushed by gnolls in the dark of night. Don\'t worry, I have plans to ensure they don\'t sneak up on me again.$B$BHere is your payment.', 0),
(94297, 0, 0, 0, 0, 0, 0, 0, 0, 'A new quiver? For me?$B$BI did not order one, but I have mentioned a few times that I would be shopping around for one soon. I imagine someone around here must have overheard that.$B$BI could not in good conscience accept this gift without payment in return. Please take this.', 0),
(94298, 0, 0, 0, 0, 0, 0, 0, 0, 'Ugh, FINALLY I am ready to make a clean getaway!$B$BUh, I mean... what? Just hurry up and give me those boots!', 0),
(94299, 0, 0, 0, 0, 0, 0, 0, 0, 'Uh, huh. Just lay \'em on a crate behind me and I\'ll deal with them later.$B$BHere\'s ye\' coin, now go bother somebody else.', 0),
(94300, 0, 0, 0, 0, 0, 0, 0, 0, 'What do ya\' think Mukomonji has planned for \'dis?$B$BNothin\'. Nothin\' at all.$B$BBut Mukomonji must have it, and will not take \"no\" for an answer. Don\' worry, mon. You get coin.', 0),
(94301, 0, 0, 0, 0, 0, 0, 0, 0, 'While my current robes serve me in my day to day, sometimes I must wear something more ceremonial in order to show my proper respect for the spirits involved in my rituals.$B$BYou did well to bring me this big voodoo robe. I will wear it proudly when the time is right.', 0),
(94303, 0, 0, 0, 0, 0, 0, 0, 0, 'Great to see that our courier still hasn\'t failed us! I\'ve been in need of a new ammo pouch to store my supply for a while.', 0),
(94304, 0, 0, 0, 0, 0, 0, 0, 0, 'You know, right after I sent out that order I realized that we probably aren\'t going to be going anywhere for a very, very long time.$B$BBut I could use a place to store my valuables before another swift-fingered rogue swipes away one of my precious stones again.$B$BHere ya\' go!', 0),
(94305, 0, 0, 0, 0, 0, 0, 0, 0, 'Yes, good. I will take these off your hands, and put them on mine.$B$BI appreciate this good deed. It will be remembered.', 0),
(94306, 0, 0, 0, 0, 0, 0, 0, 0, 'Though I am not one for vanity, I will confess that having only one set of robes shared between my everyday life and alchemical experiments has not been the greatest experience.$B$BThis robe you bring is for times of relaxation, rare as they are for me.$B$BI am further grateful to know that my crafting requests do not fall upon deaf ears. Thank you.', 0),
(94307, 0, 0, 0, 0, 0, 0, 0, 0, 'I had requested a robe made of this material for the purposes of our research. I had hoped that there would be something to learn by unraveling this robe, but even now I am beginning to doubt that there is any knowledge to be gained. Perhaps I misunderstood Greta\'s explanation and ordered the wrong item?$B$BIn any case, you went through great effort and ventured so far. I would not let you leave empty handed.', 0),
(94308, 0, 0, 0, 0, 0, 0, 0, 0, 'Wait, wait, wait! I see that pack in your backpack!$B$BNiby never lets me practice spellcasting unsupervised, and forbids me from digging through his reagents.$B$BSo, I wanted a bag of my own to start stashing things I find away! Then I\'ll do whatever I want when he\'s not watching.$B$BHand it over! Please? I\'ll pay, just don\'t mention this to the gnome!', 0),
(94309, 0, 0, 0, 0, 0, 0, 0, 0, 'This is a lovely belt, but why are you offering it to me?$B$B<A smile suddenly appears on Mylentha\'s face before you have an opportunity to respond.>$B$BThis must be Moren\'s doing. Next time he should probably claim a gift himself as to not put the burden of payment upon me as the gift\'s recipient, but I am sure he will pay me back when he sees this around my waist.$B$BYou are very kind for making this delivery. Thank you.', 0),
(94310, 0, 0, 0, 0, 0, 0, 0, 0, 'Thanks, pal!$B$B<Spek throws a handful of coins vaguely in your direction.>', 0),
(94311, 0, 0, 0, 0, 0, 0, 0, 0, 'Are theshe... pantsh?$B$B<Lolo looks down toward his equipped gear.>$B$BNot shure why I need pantsh but, I\'ll take \'em! ...hic!', 0),
(94312, 0, 0, 0, 0, 0, 0, 0, 0, 'Huh? What\'s this?$B$B<The goblin takes the shirt and examines it with an increasingly bewildered expression. Showing him the writ does not help your case.>$B$BWhat an ugly thing! I wouldn\'t be caught DEAD wearing this! Sorry pal, but I think whoever wrote this got mixed up. I\'m waitin\' for a delivery of parts, bombs, and the like. Not a shirt.$B$BI don\'t want any bad blood though, you look scary enough as it is. Take some coin for your trouble.', 0),
(94313, 0, 0, 0, 0, 0, 0, 0, 0, 'Excellent timing, $N. There has been an increase in the number of sandstorms here in Tanaris lately. The locals appreciate having some gear to prevent strong winds from kicking sand in their face.$B$BProblem is, everyone has their own idea of \'fashion\' even here in the desert, and we have to be mindful not to make our stuff look too similar to the Wastewanderer\'s equipment. Last thing we need is having our suppliers mistaken for bandits and taken out!$B$BSo it\'s time to give this mask a trial run.', 0),
(94314, 0, 0, 0, 0, 0, 0, 0, 0, 'When I was exiled from Swamp of Sorrows, I traveled far to ultimately settle here.$B$BHowever, as I am not a witherbark myself, I am not permitted to wear their ceremonial robes. I continue to wear the garb of the life I no longer live.$B$BI did not expect my plea to be heard beyond these walls. Now, humble as these robes may be, you have given me an opportunity to say my last farewell to my former life.', 0),
(94315, 0, 0, 0, 0, 0, 0, 0, 0, 'This earthen silk belt will make for a great collar for Dadanga. Thank you.', 0),
(94317, 0, 0, 0, 0, 0, 0, 0, 0, 'Your kindness today betrays your self-serving nature. All in service of what, though; a broken man from a world you will never witness?$B$BNo, of course not. You do not act benevolently for the betterment of this outlandish stranger. You act in service of your own ego, perhaps in a quest of redemption from whatever unspoken deeds have tarnished your past.$B$BDo not be insulted. You and I are much more alike than you wish to believe.', 0),
(94318, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, you\'re just here for a delivery? That\'s way less fun, but if you\'ve got that Greater Fire Protection Potion on hand, stop beating around the burnt bush and hand it over!', 0),
(94319, 0, 0, 0, 0, 0, 0, 0, 0, 'Impeccable timing, courier. The Master sends his gratitude.$B$BPlease take this payment for your troubles, on the condition that you ask no further questions and return straight to the road.', 0),
(94320, 0, 0, 0, 0, 0, 0, 0, 0, 'Though I would never call anything bestowed from that foul human a \'gift\', this Gift of Arthas will nonetheless prove valuable in my research.$B$BI anticipate my long-awaited return to Quel\'Thalas will prove challenging in ways I cannot even imagine. I hope there are lessons to be learned by studying scourged items and concoctions.', 0),
(94322, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, I have been expecting you. At times, I need to venture across the dunes toward Cenarion Hold without guard. While I can hold my own if I encounter a sand worm or tarantula, I find the silithid are too much for me.$B$BA potion like this gives me the will to charge past them, and hopefully leave them behind by the time I become vulnerable again.$B$BThank you, $N.', 0),
(94323, 0, 0, 0, 0, 0, 0, 0, 0, 'In fields wrought with death and sorrow, some old bones and broken crates are an ordinary sight.$B$BBut this little spot is different. Clearly someone was here before me, but I think nature tried to renew itself here, too. Clearly, it failed.$B$BI have been waiting for the potion you bring to arrive. I suspect nothing will come of it, but I intend to use it with the leftover herbs here in an attempt to breathe some fresh life in this corner of the plaguelands.', 0),
(94328, 0, 0, 0, 0, 0, 0, 0, 0, 'Are these the Mithril Spurs I requested? It\'s about time. Had Hastings ordered them when I first complained, these would have been my second order of replacements.$B$BHere is your payment.', 0),
(94334, 0, 0, 0, 0, 0, 0, 0, 0, 'I... What IS this? What use would I have for some flimsy, heavy crate?$B$B<Rayan skeptically listens to your description before eyeballing the compacted device.>$B$BI fail to believe that whatever is in here can withstand magical practice of our caliber, but I suppose I ought to show appreciation for your admirable efforts.$B$BHere you go. Don\'t spend it all in one place.', 0),
(94340, 0, 0, 0, 0, 0, 0, 0, 0, 'Interesting, I have not seen one of these before. I do not personally do most of the buying for Cenarion Hold, but I am in charge of keeping inventory of reagents and, apparently now, engineering parts.$B$BSomething must be stirring beneath the sands. I\'m not sure why else we are beginning to stockpile all kinds of miscellaneous goods.$B$B<Khur looks sharply at you.>$B$BKnow this: we are not ready for it. Consider any future orders from us a priority.', 0),
(94346, 0, 0, 0, 0, 0, 0, 0, 0, 'My headband? In truth, I did not expect this order of all things to be filled, especially with such consideration for time. Prior to this, I have only requested things that Karazhan at large would benefit from, or on behalf of others needing tools for their trade.$B$B... Do you think a crafting order for a new mattress would be fulfilled, too?', 0),
(94347, 0, 0, 0, 0, 0, 0, 0, 0, 'Good, our first shipment! Small as it may be, we take all we can get around here.$B$BI hope to see you or your associates again soon. If you keep the goods coming, I\'ll keep the payment flowing.', 0),
(94350, 0, 0, 0, 0, 0, 0, 0, 0, '<It would appear your delivery arrived too late, though perhaps it is of some comfort that the body has clearly been here for quite some time. The likelihood of you arriving before her demise is slim to none.$B$BRegardless, you are left with an item you otherwise have no use for, and a human paladin like yourself must sometimes resort to desperate measures for your own survival. Who is going to argue you taking your deserved earnings?>', 0),
(94355, 0, 0, 0, 0, 0, 0, 0, 0, 'What a great twist of fate! The Tuxedo Jacket has finally arrived. At last, I can go a day without the guilt-trip regarding the recent laundry mishap.$B$BSuch delightful threadwork too, my compliments to the tailor. Would that I had wealth of my own, I would consider purchasing a second so I might have one myself.', 0),
(94358, 0, 0, 0, 0, 0, 0, 0, 0, 'I did not expect a $R to be the one to deliver my mask. You will have to excuse my outburst, although I still wish you had simply left the package at the cave entrance and shuffled away.$B$BI am hiding from the Twilight\'s Hammer, you see. This mask is just another way I intend to conceal my identity. Maybe with enough coverage I might be able to leave this den worrying more about rampaging silithid rather than vengeful cultists.', 0),
(94504, 0, 0, 0, 0, 0, 0, 0, 0, 'Our burrow grows more at ease with your presence now--you have shown you are on our path, our side, and bring good things. This is the way to keep, the way we live.', 0),
(94556, 0, 0, 0, 0, 0, 0, 0, 0, 'Jom-jom saved by little one, hmm?$B$BLittle one is friend.', 0),
(94744, 0, 0, 0, 0, 0, 0, 0, 0, 'Krom\'rosh sent you? He\'s more overbearing than a milk-toothed swineherd.$B$BNot that I\'ll deny the extra muscle.', 0),
(94745, 0, 0, 0, 0, 0, 0, 0, 0, 'Listen to them scream for their gods with no answer. The only true strength is within one\'s own hands!', 0),
(94748, 0, 0, 0, 0, 0, 0, 0, 0, 'Good work, $C. $B$BMy warriors are in no condition to fight and have returned to Rog\'mar. But you and I are not done here yet.', 0),
(94768, 0, 0, 0, 0, 0, 0, 0, 0, 'I would have loved to see the look on Kilgar\'s face when you showed him just how exposed he truly was.$B$BAnd now I can.$B$B<Da\'grosh laughs as he tosses Kilgar\'s head into the dirt.>', 0),
(94823, 0, 0, 0, 0, 0, 0, 0, 0, 'You took your time arriving, $N. But you can be excused given your dedicated service to the Light. Please pay close attention to this lesson.', 0),
(94887, 0, 0, 0, 0, 0, 0, 0, 0, '<Marshal Ryan barely reacts to your approach. He looks to be on the verge of collapse.>', 0),
(94888, 0, 0, 0, 0, 0, 0, 0, 0, 'A single soldier can be the difference between us maintaining this position and the entire valley being overrun. It seems you may just be that soldier.', 0),
(94892, 0, 0, 0, 0, 0, 0, 0, 0, 'Ever dutiful till the end. Thank you for bringing this to me, $N.', 0),
(94893, 0, 0, 0, 0, 0, 0, 0, 0, 'Thank you for bringing this, $C. I understand why that coward Demar wouldn\'t show his face to me.$B$BIf you are going to stay and help them, take care of yourself. Demar is a hero, but that\'s the thing about heroes--they excel at getting other people killed.$B$B<Terry clutches Ryan\'s crest to his heart.>$B$BIdiot...', 0),
(94907, 0, 0, 0, 0, 0, 0, 0, 0, 'Well look what you\'ve brought! A little worse for wear, but this will make an excellent servant! The Twilight\'s Hammer do have a way with the dark arts, don\'t they?$B$BOh, information? Yes of course, we can interrogate my new pet on your command!', 0),
(94927, 0, 0, 0, 0, 0, 0, 0, 0, 'Dunston\'s gone back to Farholde? Finally! Next time I see him, he\'ll be paying for our drinks.$B$BThank you for the help. I might finally get to see a real bed soon.', 0),
(94975, 0, 0, 0, 0, 0, 0, 0, 0, 'A gift from our enemies, bestowed upon you.', 0),
(95122, 0, 0, 0, 0, 0, 0, 0, 0, 'I see you\'re not afraid to get your hands dirty. I like that.$B$BThanks to you, things are shaping up for us to put those scallywags down for good.', 0),
(95278, 0, 0, 0, 0, 0, 0, 0, 0, 'As a child, Da\'grosh would seek to inspire myself and the other kin of our village that some day we would all become great warriors of the Horde, saving our people from imminent danger.$B$BNow, it appears that opportunity has come.', 0),
(95284, 0, 0, 0, 0, 0, 0, 0, 0, 'Yes... I am Kor\'kron. $B$BAnd you... $C. You\'ve just been conscripted.', 0),
(95285, 0, 0, 0, 0, 0, 0, 0, 0, 'The rest of our mission details are need to know, and that\'s all you need to know. So, are you ready to do your duty to your warchief?', 0),
(95293, 0, 0, 0, 0, 0, 0, 0, 0, 'A gift from Friz? She must know when she\'s beat, harharhar!$B$BWhat is that ticking sound...?', 0),
(95294, 0, 0, 0, 0, 0, 0, 0, 0, 'Captain who? Well, whoever he is, it sounds like you two learned my next important lesson.$B$BDon\'t ever double-cross me.', 0),
(95312, 0, 0, 0, 0, 0, 0, 0, 0, 'Welcome, welcome friend! You here to participate in the notorious Gadgetzan Arena?', 0),
(95321, 0, 0, 0, 0, 0, 0, 0, 0, 'Okay you win! I bet everythin\' I had on those fights to pay off Friz and I lost it all!$B$BBut I can\'t give back her stuff. You gotta help me out here!', 0),
(95424, 0, 0, 0, 0, 0, 0, 0, 0, 'Tiny $R show strength. Ground shook with dead Twilight. Me feel from here!', 0),
(95431, 0, 0, 0, 0, 0, 0, 0, 0, '<Crag\'rog readies his mace to attack before he takes a closer look at you.>$B$BWait... Crag\'rog know you. You fight for Clugfist!', 0),
(95433, 0, 0, 0, 0, 0, 0, 0, 0, 'Morg is dead! Tiny $R full of tricks. Clugfist like you.$B$BTwilight\'s Hammer crumple beneath might of Bolder\'ok. We free ogres!', 0),
(95643, 0, 0, 0, 0, 0, 0, 0, 0, 'You managed to put down a fair number of those beasts. The Twilight\'s Hammer will reel at their losses today.', 0),
(95753, 0, 0, 0, 0, 0, 0, 0, 0, '<Nature magic pulses through the totem. It has deemed you worthy of reward.>', 0),
(95924, 0, 0, 0, 0, 0, 0, 0, 0, 'Thank you, $C! You\'ve made our digsite safe, but more importantly you\'ve made it safe for us to collect the belongings of those we lost. I know their families will thank ye as well for this.$B$BAnyhow, I will send a team out immediately! I can\'t wait to hear what wonders they will discover there.', 0),
(95983, 0, 0, 0, 0, 0, 0, 0, 0, '<Cornelius runs his fingers along the markings left on the skull. His brow furrows more and more as he does so.>$B$BJust what I needed...more work. You\'ve got me into a real mess, you know that?', 0),
(96015, 0, 0, 0, 0, 0, 0, 0, 0, 'I\'m not sure what kind of politics we got ourselves into, but a dead ogre is always a win in my book. If we can keep them off balance, they won\'t have time to recuperate.', 0),
(96060, 0, 0, 0, 0, 0, 0, 0, 0, 'Marvelous! Spectacular even! After all these years, I am delighted to hear that this sword managed to shed blood at least once in its existence.$B$BAnd those ghosts you saw--what an unexpected, peculiar surprise. I am less enthusiastic about that, as it likely means we will need to eradicate those same creatures a second time if they have managed to entangle themselves in our spirit realm.$B$BNot a task I intend to bother you with, at least not today. Carry on with whatever it is you are doing here.', 0),
(96085, 0, 0, 0, 0, 0, 0, 0, 0, 'A giant rotting turtle? And we were drinking its... I\'d rather not think of what.$B$BNo wonder these soldiers were so ill.$B$BThis has been quite the unusual investigation, but you have handled it all with a sense of duty and bravery. I must commend you for that.$B$BWhether they know it or not, everyone in Farholde owes their safety to you.', 0),
(96126, 0, 0, 0, 0, 0, 0, 0, 0, 'You have the key! Excellent! I am beyond grateful, $N. $B$BNow, let\'s get out of here.', 0),
(96302, 0, 0, 0, 0, 0, 0, 0, 0, 'I sense the absolution is complete. We can all take deeper breaths, now.', 0),
(96322, 0, 0, 0, 0, 0, 0, 0, 0, '<The crow looks bemused as you recount your time with Felflick and what you\'ve learned.>$B$BOh, no. The key didn\'t work? Shame. I guess any old key you find in the dirt might not be the correct one, hum? But what would a little crow like me know of such things?$B$BAnd you\'re sure they said the word \'Blackthorne\'? Interesting.$B$BAnyhow, two demons with one stone as they say. It would seem we\'ve at least stemmed the threat for the time being.$B$BWell done, dirtwalker. I hereby pronounce you as my underwing!', 0),
(96332, 0, 0, 0, 0, 0, 0, 0, 0, 'I hope you made them suffer, $C!', 0),
(96334, 0, 0, 0, 0, 0, 0, 0, 0, 'I thank you for bringing me these bandanas. There is no doubt in my mind that they are Defias Brotherhood masks. We had our suspicions that they were the ones operating the prison on Alcaz, but this confirms it.$B$BI will inform Thrall of this.', 0),
(96559, 0, 0, 0, 0, 0, 0, 0, 0, 'You find what can be none other than the pilot survival kit Fenwick Togglespring was speaking about, in relatively unscathed condition.', 0),
(96622, 0, 0, 0, 0, 0, 0, 0, 0, 'I appreciate what you have done, $C. It may seem inconsequential, but you have made a true impact on our lives here.$B$BI wish I had more to give you than just my gratitude and the recipe for a simple salve. I\'m afraid we have very little to offer you here in terms of rewards for your deeds.$B$BStill, you are always welcome at our camp, and should I ever escape this forsaken mountain you are always welcome at my fire.', 0),
(96674, 0, 0, 0, 0, 0, 0, 0, 0, 'The sheep! YES! Now I won\'t get in trouble! Thanks for finding them all.$B$B<Mirt smiles and seems satisfied with the returned sheep.>$B$BOh, is that a real weapon? Can I see it? Where did you come from, anyway? Does it smell different there? Are you gonna stay here forever? What does snow look like? Have you ever seen a dragon??', 0),
(96785, 0, 0, 0, 0, 0, 0, 0, 0, 'Why you...where did you find that!?$B$B<Anastasia takes a moment to compose herself.>$B$BFine. I\'ll tell you about the deal. Just give me that back, and we\'ll call it even.', 0),
(96786, 0, 0, 0, 0, 0, 0, 0, 0, 'Well well, you seem to have acquired this through no small effort. You play the game of subterfuge well.$B$BIf you are wondering about the content of this package, I hope you understand that is on a need-to-know basis.$B$BNevertheless, you have served the manor honorably. For that, you certainly ought to be rewarded.', 0),
(96912, 0, 0, 0, 0, 0, 0, 0, 0, 'Alright, alright... good enough! Remember, this journey has just started. Return to me soon and I\'ll give ya another challenge.', 0),
(96979, 0, 0, 0, 0, 0, 0, 0, 0, 'The way ahead is clear if I stay on the road? Harpies are exactly the kind of enemy I\'m trying to avoid. $B$BThank you, and for refilling the gourd. I hope you took the time to refresh yourself at the falls while you were there.$B$BWhen I perform my rituals of blessing, I will use this water to honor the mountain\'s past and its caretaking spirits.', 0),
(97048, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, ye must be $N. Mathers tells me ye busted out of Kurzen\'s compound together. Said the two of ye really let some heads roll. Some proper swashbucklers the pair of ye are!$B$B<Captain Aransas pauses to gauge your reaction.>$B$BHa har! I know it\'s all a fib, matey. Mathers is a good boy, but the only blade he\'s fit to wield is a kitchen knife.$B$BAll the same, I appreciate ye saving a member of me crew. A good cook is priceless in this line o\' work.', 0),
(97171, 0, 0, 0, 0, 0, 0, 0, 0, 'Excellent, $N! I can see you\'ve made a choice, and what a fine pick it is.$B$BI\'m proud to be able to provide you with one of our horses. I must say the one you have picked seems fond of you already! I hope you will take good care of it, and it of you.$B$BCome back if you ever need new horseshoes! They\'re on the house.', 0),
(97173, 0, 0, 0, 0, 0, 0, 0, 0, 'Excellent work, $N.$B$BMy colleague and I are most eager to study and catalog the magic permeating this totem.', 0),
(97327, 0, 0, 0, 0, 0, 0, 0, 0, 'You have shown yourself to be a stalwart ally in times of strife. Though there will be tears, the people of Ursolan will be grateful for these mementos.', 0),
(97404, 0, 0, 0, 0, 0, 0, 0, 0, 'Nature will bring herself two new great matriarchs to replace these elderly souls.$B$BThank you for ending their struggle against time and the elements.$B$BWith the earnest territorial guard mothers permanently at rest, we can settle a camp more easily, and keep to ourselves. This will, in turn, bring even more serenity back to this wilderness.', 0),
(97536, 0, 0, 0, 0, 0, 0, 0, 0, 'How are your hands looking? Can you still feel your digits?$B$BI wouldn\'t worry, it should fade soon. Now we can observe them from a safe distance!$B$BThanks, $N.', 0),
(97663, 0, 0, 0, 0, 0, 0, 0, 0, 'My supplies! And did you manage to--$B$B<Mus\'hale finds the scrawled parchment first thing upon opening the supply bag.>$B$BYour aid is greatly appreciated, $N. With my belongings and some material to study, I\'ve got more than enough to pass the time during my recovery. And I can afford to sleep inside the hut tonight.$B$BFarewell, friend.', 0),
(98096, 0, 0, 0, 0, 0, 0, 0, 0, 'Sentinel Keldara is one of our best. I wish her sister well.$B$BShe was dispatched to monitor satyr activity in the Haldarr Encampment to the northeast. You look like you\'re able to hold your own--I would appreciate your aiding her on her mission.$B$BWe cannot afford more loss in our ranks.', 0),
(98205, 0, 0, 0, 0, 0, 0, 0, 0, 'This is great! I\'m happy to see you back in one piece and relatively un-burnt!$B$BYa know, you\'ve been a solid business partner. Not many folks would dive head-long into helping someone else out without payment first.$B$BFeel free to take something nice from one of the crates for your effort.', 0),
(98215, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, wow! You got a lot more than I expected.$B$BSo did you wind up finding them on the ground or did you punch them off a dragon?$B$BEither way, I won\'t let any of them go to waste!$B$BHere, your coin as promised.', 0),
(98417, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh no... words like these do not bring me comfort. Kurothel must be more than living in the wild, he\'s living more like a wild beast each passing night.$B$BI fear the whispers must be true.', 0),
(98418, 0, 0, 0, 0, 0, 0, 0, 0, 'There was a welling up of... Elune\'s light within and around me. I feel Kurothel has witnessed your act of battle within this war that rages within our land, and within our hearts. $B$BMy hopes are that with time, the efforts of our Sentinels and our wayward druids will eliminate the demonic menace once and for all. Perhaps then and only then will the feral drive for vengeance burn out from our lineage\'s heritage.$B$BThank you, $N. You are a child of the forest, and a valuable spearhead of Kaldorei will.', 0),
(99258, 0, 0, 0, 0, 0, 0, 0, 0, 'It worked! It worked!!$B$BI struggle to find words, $N! I did not expect this to prove successful. With each passing decade I worried that whatever chance there might have been had passed.$B$BThis may seem unimportant or perhaps even mundane to you, but rest assured that this is unlife changing for us.$B$BI will begin planning next steps. I have no further tasks for you, but others might appreciate your aid.$B$BThank you. Truly.', 0),
(99435, 0, 0, 0, 0, 0, 0, 0, 0, '<Bolvar holds the shattered medallion.>$B$BThe magic held within must be reignited. The dragon\'s eye must be attuned.$B$BWindsor\'s sacrifice has freed our Kingdom, but the threat of Onyxia and her kin is ever looming.$B$BThis medallion is what held my mind and body captive. It is also what gave me access to Onyxia\'s own mind - to her secrets. Albeit the visions are muddled now, some things I do remember.', 0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) SELECT `ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild` FROM `everlake_forge_stage`;
INSERT IGNORE INTO `everlake_import_rows` (`tbl`, `k1`, `k2`, `k3`, `k4`, `file`, `note`) SELECT 'quest_offer_reward', s.`ID`, 0, 0, 0, '2026_11_19_900_world_everlake_forge_00196_import.sql', 'Forge #196: Icy Veins 2026-11-19' FROM `everlake_forge_stage` s;
INSERT INTO `everlake_forge_stage` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `EmoteOnCompleteDelay`, `EmoteOnIncompleteDelay`, `CompletionText`, `VerifiedBuild`) VALUES
(86746, 0, 0, 0, 0, 'I appreciate your aid, $N. My tribe are wary of others, but we can no longer fight the satyr alone.', 0),
(88807, 0, 0, 0, 0, 'There is much to be done in our fight against the Spitelash, and few hands to do it.', 0),
(88809, 0, 0, 0, 0, 'Many Kaldorei would write off this land as a lost cause, and leave the ruins to the naga, but I believe our history is worth fighting for.', 0),
(91548, 0, 0, 0, 0, 'Jediga did well to send you. I will have to thank her when she returns from Azshara.', 0),
(92009, 0, 0, 0, 0, 'Haven\'t found yourself around Winterspring either, huh? That\'s okay, I\'ve got plenty around here to do in the meantime!', 0),
(92064, 0, 0, 0, 0, '<Fenwick\'s parachute is shredded, tangled and wrapped up in the branches of the tree in such a manner that he\'s essentially immobile, dangling bait.>', 0),
(92102, 0, 0, 0, 0, '...', 0),
(92328, 0, 0, 0, 0, 'You can crawl under it or use the ladder, it\'s not going anywhere. I\'ll work the connections from here. Give those gears on both sides a strong turn, and connect the battery cables to the positive and negative terminals!', 0),
(92754, 0, 0, 0, 0, 'My patience runs thin, outsider.', 0),
(92872, 0, 0, 0, 0, 'Even this place of solemn death has an influx of new matter. Releasing it back into the light in such a manner is meant to represent the draw towards the seeds of new life.', 0),
(92959, 0, 0, 0, 0, 'The pain of the fel energy that courses through me is nothing compared to the sorrow of watching my friends suffer.', 0),
(93016, 0, 0, 0, 0, 'Do you have further questions?', 0),
(93066, 0, 0, 0, 0, 'Ah. You must be the outsider running favors for Orgrul.$B$BHow lucky you are that you are terrible at sneaking around. Had my scouts not seen you stomping around on his behalf, your head would be on a bloodied pike.', 0),
(93362, 0, 0, 0, 0, 'Is it done?', 0),
(93404, 0, 0, 0, 0, '<Woodwyrd stands, nearly motionless. He stares through you, just as you once might have stared through the ghosts of Shen\'dralas.>', 0),
(93422, 0, 0, 0, 0, 'We must stop the Blackthorne druids from extending the Wild King\'s reach!', 0),
(93604, 0, 0, 0, 0, 'You back? You bring blood, or Kog\'thug spill it from you!', 0),
(93606, 0, 0, 0, 0, '<Quolga looks at you with a confused expression and nearly-crossed eyes.>$B$BWhat you want with Quolga? Did Kog\'thug send you, too?', 0),
(93833, 0, 0, 0, 0, 'The owls, while sleek and serene, are capable of viciously ending life in moments. Be alert!', 0),
(94220, 0, 0, 0, 0, 'It is unwise to sneak up on me, $R. Speak quickly, and speak quietly.', 0),
(94224, 0, 0, 0, 0, 'Shh. Keep your voice down. I\'m not ready for a fight, yet.', 0),
(94225, 0, 0, 0, 0, 'What\'s up?', 0),
(94226, 0, 0, 0, 0, 'Here for your daily punching?', 0),
(94228, 0, 0, 0, 0, 'Please tell me you\'re the one with the boots...', 0),
(94232, 0, 0, 0, 0, 'Do we have business?', 0),
(94234, 0, 0, 0, 0, 'Hey! Watch where you\'re walking!', 0),
(94236, 0, 0, 0, 0, 'You got the stuff?', 0),
(94237, 0, 0, 0, 0, 'Here to buy, or sell?', 0),
(94238, 0, 0, 0, 0, '<Sos\'mol has been singing off-key to an improvised song well before your arrival. He continued singing albeit in a quieter voice as you approached. He seemed slightly embarrassed, but clearly not embarrassed enough to cease his humming about boredom.>', 0),
(94239, 0, 0, 0, 0, 'Move along, please, and try not to draw attention to us.', 0),
(94240, 0, 0, 0, 0, 'Ah, you look as though you are here to make a delivery. Take a moment to catch your breath.', 0),
(94242, 0, 0, 0, 0, 'Buying, or selling?', 0),
(94244, 0, 0, 0, 0, 'Yarr, what business do ye\' have with ol\' Narkk?', 0),
(94245, 0, 0, 0, 0, 'Sign-ups are closed, bud. Besides, you look a little too big to fit in one of our carts.', 0),
(94246, 0, 0, 0, 0, 'Whatcha got for me?', 0),
(94250, 0, 0, 0, 0, 'Yo! Is that pack for me?', 0),
(94251, 0, 0, 0, 0, 'You come get \'da voodoo?', 0),
(94252, 0, 0, 0, 0, 'Yo!', 0),
(94253, 0, 0, 0, 0, 'Keep ya\' head down, mon! Dey be watching...', 0),
(94257, 0, 0, 0, 0, 'What business could a $R possibly have with me?', 0),
(94258, 0, 0, 0, 0, 'Puny $C bring Mudcrush food?$B$BMudcrush eat you if not...', 0),
(94259, 0, 0, 0, 0, 'Have you come to aid the Emerald Circle?', 0),
(94260, 0, 0, 0, 0, 'You never know what lurks in the forest.', 0),
(94261, 0, 0, 0, 0, 'Greetings, tauren $C. I hope you are enjoying your stay in Moonglade.', 0),
(94262, 0, 0, 0, 0, 'We don\'t have business. Move along, pal.', 0),
(94264, 0, 0, 0, 0, 'Stand back, mon.', 0),
(94265, 0, 0, 0, 0, 'Well, if you\'re not here to shop, then what is it?', 0),
(94266, 0, 0, 0, 0, '<Juo seems uninterested in your presence, but a slight flick of an ear indicates she heard your approach.>', 0),
(94267, 0, 0, 0, 0, 'Please tell me you\'re either taking me out of here or brought me booze...', 0),
(94268, 0, 0, 0, 0, 'You\'re not my boss, go away.', 0),
(94269, 0, 0, 0, 0, 'Watch where you\'re walking! These bones are worth more than three whole $R skeletons!', 0),
(94270, 0, 0, 0, 0, 'Sometimes friend is foe, and try to steal Ugbert\'s club.', 0),
(94271, 0, 0, 0, 0, 'How can Taronn Redfeather help you?', 0),
(94272, 0, 0, 0, 0, 'Hello, $C.', 0),
(94273, 0, 0, 0, 0, 'Moonglade is not the place for violence, but I keep weapons stocked when the time calls for it.', 0),
(94274, 0, 0, 0, 0, 'Listen, I am expecting a very BIG delivery and I can\'t have you getting in the way.', 0),
(94275, 0, 0, 0, 0, 'Whether you want metal or meat, I\'ve got it for sale.', 0),
(94276, 0, 0, 0, 0, 'Whatchu want?', 0),
(94277, 0, 0, 0, 0, 'Yo! Can you help me fix this?', 0),
(94279, 0, 0, 0, 0, 'Greetings, traveler.', 0),
(94280, 0, 0, 0, 0, '...and then we can set up a rocket network across all of-- OH! My goodness I didn\'t see you there! How long have you been listening to me yap to myself?$B$BHow embarrassing!', 0),
(94281, 0, 0, 0, 0, 'The other day I saw a whole herd of centaur galloping across the Desolace. One of them looked me right in the eye as he passed, and I swear he\'s got it out for me now!$B$BAny chance you can help a goblin out?', 0),
(94282, 0, 0, 0, 0, '<The slime blurbles greedily.>', 0),
(94283, 0, 0, 0, 0, 'Careful where you wander in Felwood, $R. Many get lost, never to return.', 0),
(94284, 0, 0, 0, 0, 'Have you come to join me in the hunt?', 0),
(94285, 0, 0, 0, 0, 'Greetings, traveler. Can I interest you in a new bow?', 0),
(94286, 0, 0, 0, 0, 'What am I doing here? What are YOU doing here?!', 0),
(94288, 0, 0, 0, 0, 'Hey, can I interest you in a scouting mission?', 0),
(94289, 0, 0, 0, 0, 'Oh gosh! Oh my! Oh no!', 0),
(94290, 0, 0, 0, 0, 'Huh? ...Hiccup!', 0),
(94292, 0, 0, 0, 0, 'Yes?', 0),
(94293, 0, 0, 0, 0, 'Have you come to join me in studying the mysteries behind Ethel Rethor?', 0),
(94294, 0, 0, 0, 0, '<The slime acknowledges your presence by drooling profusely.>', 0),
(94295, 0, 0, 0, 0, 'You are welcome here in the Emerald Sanctuary, but I suspect you have business with Greta or Eridan, not me.', 0),
(94296, 0, 0, 0, 0, 'You look ready to hand over some equipment.', 0),
(94297, 0, 0, 0, 0, 'Looking to buy a bow?', 0),
(94298, 0, 0, 0, 0, '<The goblin peers left and right before looking up at you.>$B$BCoast is clear. Make it quick.', 0),
(94299, 0, 0, 0, 0, 'Eh huh?', 0),
(94300, 0, 0, 0, 0, 'Stay away from my voodoo!', 0),
(94301, 0, 0, 0, 0, 'What can I do for you?', 0),
(94303, 0, 0, 0, 0, 'I\'ve got the finest wares in all of Un\'Goro Crater!', 0),
(94304, 0, 0, 0, 0, 'Hey, how\'re ya doing?', 0),
(94305, 0, 0, 0, 0, 'Are you lost, $R?', 0),
(94306, 0, 0, 0, 0, 'You are far away from home, $R.', 0),
(94307, 0, 0, 0, 0, 'How can I help?', 0),
(94308, 0, 0, 0, 0, 'Go bother master!', 0),
(94309, 0, 0, 0, 0, 'You are welcome to join me, but please do not disturb my meditation.', 0),
(94310, 0, 0, 0, 0, 'Whoa! What\'s that in your backpack?', 0),
(94311, 0, 0, 0, 0, 'What can ye\' do for me... hic!', 0),
(94312, 0, 0, 0, 0, 'Keep your feet out of the water if you know what\'s good for you!', 0),
(94313, 0, 0, 0, 0, 'Are you here for the delivery?', 0),
(94314, 0, 0, 0, 0, 'You should not be here, $C.', 0),
(94315, 0, 0, 0, 0, 'Have you come to feed the kodo? Visitors to Marshal\'s Refuge love a chance to feed her.', 0),
(94316, 0, 0, 0, 0, 'Hm, you should consider yourself fortunate that I tolerate your presence in my tower uninvited. This had better be good.', 0),
(94317, 0, 0, 0, 0, 'You reek of greed.', 0),
(94318, 0, 0, 0, 0, 'Ooh, you look like you\'re made of great parts! Ever wanted to be mixed into a potion?', 0),
(94319, 0, 0, 0, 0, 'Are you here on a delivery? If not, I am afraid I will have to send you away.', 0),
(94320, 0, 0, 0, 0, 'Greetings.', 0),
(94322, 0, 0, 0, 0, 'Greetings, friend of the Cenarion Circle.', 0),
(94323, 0, 0, 0, 0, 'I could not help but be drawn to this landmark as I was passing. It is so strange. Wouldn\'t you agree?', 0),
(94328, 0, 0, 0, 0, '<A nearby Spectral Charger neighs sternly in greeting before Calliard says a word. He nods in agreement with it.>', 0),
(94334, 0, 0, 0, 0, 'Are you aware that you are tracking mud with every step? If you can\'t be bothered to wipe your soles on entry, consider taking off your shoes before storming through someone else\'s domain.', 0),
(94340, 0, 0, 0, 0, 'Need reagents, paladin?', 0),
(94346, 0, 0, 0, 0, 'Greetings, I hope you are the courier I was expecting, else I am afraid you will have to turn around and return home.', 0),
(94347, 0, 0, 0, 0, 'Supplies are runnin\' low. Still have plenty available if you have earned your rank, but don\'t be expecting any discounts.', 0),
(94350, 0, 0, 0, 0, '<The body before you is motionless.>', 0),
(94355, 0, 0, 0, 0, 'Excuse me, traveler, but we are not allowing guests at this point in time.', 0),
(94358, 0, 0, 0, 0, 'I said go away!', 0),
(94504, 0, 0, 0, 0, 'We are not there yet, as one tribe, but in time your name will bring the trust you seek.', 0),
(94556, 0, 0, 0, 0, 'Hm?', 0),
(94727, 0, 0, 0, 0, 'What you want? Me not supposed to talk to strangers.', 0),
(94745, 0, 0, 0, 0, 'Soak these plains with Twilight blood! These lands belong to the Horde!', 0),
(94748, 0, 0, 0, 0, 'The Twilight Champions likely hold the keys to my warrior\'s cages. Slay them and free our people.', 0),
(94768, 0, 0, 0, 0, 'The coward is sure to be hiding deep within his stronghold. Bring me his head that we may put an end to this blight.', 0),
(94888, 0, 0, 0, 0, 'If you run into any horde captives, let them rot in their cells. One less headache to worry about.', 0),
(94892, 0, 0, 0, 0, 'Did you find the Marshal?', 0),
(94893, 0, 0, 0, 0, 'I suppose it was only a matter of time before someone came asking about Ryan. $B$BWhen his family was killed during the orc invasion, something changed in him. His vendetta against the Horde warped from a sense of duty into an all-consuming hatred. I tried to convince him to come live with my parents and me here in Stormwind but he wouldn\'t budge. He swore to remain until he purged his home of the orcs.$B$BWe hadn\'t spoken since.', 0),
(94907, 0, 0, 0, 0, 'Well? Did you do it?', 0),
(94975, 0, 0, 0, 0, 'Vengeance is best born of blood.', 0),
(95122, 0, 0, 0, 0, 'The Eastsea\'s cannons are one thing. Any goblin can handle a few fireworks. It\'s the raiders that scare me. Froth-mouthed axe-wielding maniacs? No thank you!', 0),
(95285, 0, 0, 0, 0, 'Any questions, recruit?', 0),
(95293, 0, 0, 0, 0, 'Yer lucky I don\'t split ye stem to stern fer steppin\' on me ship, landlubber! Give me one reason I shouldn\'t keelhaul yer right now!', 0),
(95321, 0, 0, 0, 0, 'O-oh! Just the orc I was lookin\' for!', 0),
(95424, 0, 0, 0, 0, 'You no smash, you not stay!', 0),
(95433, 0, 0, 0, 0, 'Crag\'rog say you join him in fight. What you bring mighty Clugfist?', 0),
(95601, 0, 0, 0, 0, 'Me wait here for friends. Thinking hurt Clubtoe head.', 0),
(95983, 0, 0, 0, 0, 'Now what is it?', 0),
(96015, 0, 0, 0, 0, 'There\'s something off about the ogres in the mines. They almost seem docile. Whatever the Twilight\'s Hammer are doing to them, they\'ve left themselves wide open.', 0),
(96085, 0, 0, 0, 0, 'I wish I had more guidance to give you, but this is all a far cry from my field of study.', 0),
(96126, 0, 0, 0, 0, 'I\'m glad someone finally found me. I don\'t know how many more days I could have survived.', 0),
(96322, 0, 0, 0, 0, 'Dirtwalker! It would seem you are sans the key I gave you? Does this mean our friend was willing to strike a deal?', 0),
(96332, 0, 0, 0, 0, 'Blood and thunder!', 0),
(96334, 0, 0, 0, 0, 'What is this, $C?', 0),
(96666, 0, 0, 0, 0, 'Barkskin trust slow, but speak true.', 0),
(96674, 0, 0, 0, 0, 'PLEASE don\'t tell my mom! She would be so mad if she found out I was off playing instead of watching the sheep.$B$BI know I\'m supposed to watch them, but the sheep are so BORING. I wish I had anyone other than sheep to play with.$B$B<Mirt kicks the dirt.>$B$BOh, hey do you wanna see my sword stick? It\'s really cool. I found it yesterday.', 0),
(96785, 0, 0, 0, 0, 'I told you already, I\'ve got nothing for you. Now beat it!', 0),
(96786, 0, 0, 0, 0, 'Ah, $N, I see you\'ve returned from Stromgarde.', 0),
(96912, 0, 0, 0, 0, 'Now I better not hear you did some cheesy, cheat strategy to get this challenge done. Only chumps throw duels!', 0),
(96913, 0, 0, 0, 0, 'How goes it, pal?', 0),
(96979, 0, 0, 0, 0, 'I need to spend more time in the hills. This thin air demands much from the body.', 0),
(97171, 0, 0, 0, 0, 'You\'ve returned! Have you made your choice? These horses are some of the finest this side of the Eastern Kingdoms.$B$BYou won\'t find a more courageous steed.', 0),
(97173, 0, 0, 0, 0, 'Spell focus objects can tell us much about the nature of magic being channeled through them. Magic always leaves some sort of lingering \"footprint\", as it were.', 0),
(97327, 0, 0, 0, 0, 'Have you located any of my people\'s belongings?', 0),
(97331, 0, 0, 0, 0, 'I\'d ask if you\'re making a delivery but I see no crate. What business do we have?', 0),
(97404, 0, 0, 0, 0, 'Winterspring is merciless to the weak and aging. The elderly matriarchs won\'t last many seasons more, and dying of cold when you\'re feeble is not a noble end.', 0),
(97536, 0, 0, 0, 0, 'I\'ve slapped on some labels that say hazardous and toxic... that way people know to leave them be after you find them a new home in the desert.', 0),
(97663, 0, 0, 0, 0, 'Have you any luck?', 0),
(98215, 0, 0, 0, 0, 'Did you find any scales? The sooner I have those the safer I\'ll potentially feel. Well, if this theory pans out, anyway.', 0),
(98417, 0, 0, 0, 0, 'What have you found within the hills of our forest?', 0),
(98418, 0, 0, 0, 0, 'Demons disgrace our ancient culture. They compel our defensive instincts to bare themselves at their most primal. Will we lose ourselves in the strife?', 0),
(99258, 0, 0, 0, 0, 'I look forward to the results of this experiment. I have watched the arcane energies of this place dwindle over many years, and I fear we are now more vulnerable than ever.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `EmoteOnCompleteDelay`, `EmoteOnIncompleteDelay`, `CompletionText`, `VerifiedBuild`) SELECT `ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `EmoteOnCompleteDelay`, `EmoteOnIncompleteDelay`, `CompletionText`, `VerifiedBuild` FROM `everlake_forge_stage`;
INSERT IGNORE INTO `everlake_import_rows` (`tbl`, `k1`, `k2`, `k3`, `k4`, `file`, `note`) SELECT 'quest_request_items', s.`ID`, 0, 0, 0, '2026_11_19_900_world_everlake_forge_00196_import.sql', 'Forge #196: Icy Veins 2026-11-19' FROM `everlake_forge_stage` s;
